import { expect, test } from './fixtures';

/**
 * GET STARTED's SET UP part (the Getting Started handoff, board 1), in a real
 * browser, on /start: the same list the empty library shows, which the shared
 * seeded server can't (its library isn't empty). The holds table's rows and
 * the list's own frame are left out: both are closed blocks now
 * (doc/ONBOARDING.md, "Where it departs from the handoff").
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/design/handoff/Start-Checklist.dc.html
 * Extracted at 2026-11-01T00:20:29.196Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region2: '.step[data-step="repo"] .st-text',
	region3: '.step[data-step="repo"] .st-body',
	region4: '.step[data-step="repo"] form.field',
	region8: '.step[data-step="repo"] .st-body > .field:last-child',
	region9: '.step[data-step="repo"] .seek',
	region10: '.step[data-step="repo"] .seek .chip:nth-child(1)',
	region12: '.step[data-step="ext"] .st-text',
	region14: '.step[data-step="phone"] .st-text'
};

test('00 — GET STARTED0 OF 4 DONE · ANY ORDER — Nothing here yet.: frame matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/start`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('00 — GET STARTED0 OF 4 DONE · ANY ORDER — Nothing here yet.: region2 matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/start`);
	await expect(page.locator(SEL.region2)).toBeVisible();

	const region2Style = await page.locator(SEL.region2).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			flexDirection: cs.flexDirection,
			justifyContent: cs.justifyContent,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom
		};
	});
	expect(region2Style.display).toBe('flex');
	expect(region2Style.flexDirection).toBe('column');
	expect(region2Style.justifyContent).toBe('center');
	expect(region2Style.rowGap).toBe('6px');
	expect(region2Style.columnGap).toBe('6px');
	expect(region2Style.paddingTop).toBe('14px');
	expect(region2Style.paddingRight).toBe('16px');
	expect(region2Style.paddingBottom).toBe('14px');
});

